-- +goose Up
CREATE TABLE "protocols" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text UNIQUE NOT NULL
);

CREATE TABLE "configs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "public_id" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "name" varchar(255) NOT NULL,
  "ip_address" varchar(15) NOT NULL,
  "protocol_id" smallint NOT NULL,
  "server_id" smallint NOT NULL,
  "subscription_id" bigint NOT NULL,
  "status" text NOT NULL DEFAULT 'active',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_status_is_known" CHECK (status IN ('active', 'suspended'))
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "public_id" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "username" text UNIQUE,
  "telegram_id" bigint UNIQUE,
  "password_hash" text,
  "is_admin" boolean NOT NULL DEFAULT false,
  CONSTRAINT "chk_has_identity" CHECK ((username IS NOT NULL AND password_hash IS NOT NULL) OR telegram_id IS NOT NULL),
  CONSTRAINT "chk_username_password_pair" CHECK ((username IS NULL) = (password_hash IS NULL))
);

CREATE TABLE "subscriptions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint UNIQUE NOT NULL,
  "status" text NOT NULL DEFAULT 'active',
  "current_period_end" timestamptz,
  "canceled_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "quantity" int NOT NULL,
  "payment_claimed_at" timestamptz,
  CONSTRAINT "chk_status_is_known" CHECK (status IN ('active', 'pending', 'past_due')),
  CONSTRAINT "chk_pending_has_claim" CHECK ((status = 'pending') = (payment_claimed_at IS NOT NULL)),
  CONSTRAINT "chk_quantity_positive" CHECK (quantity >= 1)
);

CREATE TABLE "servers" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "public_id" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "public_address" text NOT NULL,
  "internal_address" text NOT NULL,
  "location" varchar(2) NOT NULL,
  "location_country" text NOT NULL,
  "location_city" text NOT NULL
);

CREATE TABLE "access_codes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(8) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE UNIQUE INDEX "unq_config_ip_per_server" ON "configs" ("server_id", "protocol_id", "ip_address");

COMMENT ON COLUMN "configs"."status" IS 'Config''s status';

COMMENT ON COLUMN "subscriptions"."user_id" IS 'One user per subscription';

COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'End of the subscription period';

COMMENT ON COLUMN "subscriptions"."quantity" IS 'Keys bought';

COMMENT ON COLUMN "subscriptions"."payment_claimed_at" IS 'User asserted payment, awaiting confirmation';

ALTER TABLE "configs" ADD FOREIGN KEY ("subscription_id") REFERENCES "subscriptions" ("id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "configs" ADD FOREIGN KEY ("protocol_id") REFERENCES "protocols" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "configs" ADD FOREIGN KEY ("server_id") REFERENCES "servers" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "subscriptions" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

